#!/usr/bin/env python3
"""Public fixture matcher and bounded real CLI execution; no task evaluator."""
import json
import os
from pathlib import Path
import selectors
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
from limits import apply


def strict_json(raw):
    def pairs(items):
        out={}
        for key,value in items:
            if key in out:raise ValueError('duplicate key')
            out[key]=value
        return out
    def bad(value):raise ValueError('nonfinite JSON')
    return json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_constant=bad)


def matches(actual, expected):
    if type(actual) is not type(expected):return False
    if isinstance(expected,dict):
        return set(actual)==set(expected) and all(matches(actual[k],v) for k,v in expected.items())
    if isinstance(expected,list):
        return len(actual)==len(expected) and all(matches(a,b) for a,b in zip(actual,expected))
    return actual==expected


def freeze(source,dest):
    source=Path(source)
    if source.is_symlink() or not source.is_dir():raise ValueError('submission must be a regular directory')
    dest.mkdir()
    entries=0;total=0
    for base,dirs,files in os.walk(source,followlinks=False):
        rel=Path(base).relative_to(source)
        for name in dirs+files:
            path=Path(base)/name;st=path.lstat();entries+=1
            if entries>512:raise ValueError('submission entry budget exceeded')
            if stat.S_ISDIR(st.st_mode):
                (dest/rel/name).mkdir();continue
            if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:
                raise ValueError('submission links/special files are unavailable')
            total+=st.st_size
            if total>16*1024**2:raise ValueError('submission byte budget exceeded')
            fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
            with os.fdopen(fd,'rb') as src,(dest/rel/name).open('xb') as out:
                fst=os.fstat(src.fileno())
                if (fst.st_dev,fst.st_ino,fst.st_size,fst.st_mtime_ns)!=(st.st_dev,st.st_ino,st.st_size,st.st_mtime_ns):
                    raise ValueError('submission changed during collection')
                copied=0
                while True:
                    block=src.read(min(65536,st.st_size-copied+1))
                    if not block:break
                    copied+=len(block)
                    if copied>st.st_size:raise ValueError('submission grew during collection')
                    out.write(block)
                if copied!=st.st_size or os.fstat(src.fileno()).st_mtime_ns!=st.st_mtime_ns:
                    raise ValueError('submission changed during collection')
            (dest/rel/name).chmod(0o444)
    if not (dest/'main.py').is_file():raise ValueError('submission/main.py is required')


def capture(entry,data,cwd):
    vendor=Path(__file__).resolve().parent/'vendor'
    if not vendor.is_dir():vendor=Path('/workspace/vendor')
    p=subprocess.Popen([sys.executable,'-I','-B',str(entry)],stdin=subprocess.PIPE,
                       stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd=cwd,preexec_fn=apply,
                       close_fds=True,env={'PATH':'/usr/local/bin:/usr/bin:/bin','LANG':'C',
                       'TMPDIR':str(cwd),'PYTHONHASHSEED':'0','OPENBLAS_NUM_THREADS':'1',
                       'OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1','NETNOMOS_DEPS':str(vendor)})
    streams=[p.stdin,p.stdout,p.stderr];selector=selectors.DefaultSelector()
    output=[bytearray(),bytearray()];offset=0;deadline=time.monotonic()+180
    try:
        for stream in streams:os.set_blocking(stream.fileno(),False)
        selector.register(p.stdin,selectors.EVENT_WRITE,-1)
        selector.register(p.stdout,selectors.EVENT_READ,0)
        selector.register(p.stderr,selectors.EVENT_READ,1)
        while selector.get_map():
            if time.monotonic()>=deadline:raise ValueError('candidate wall deadline exceeded')
            for key,_ in selector.select(.1):
                stream,index=key.fileobj,key.data
                if index==-1:
                    try:offset+=os.write(stream.fileno(),data[offset:offset+65536])
                    except BlockingIOError:continue
                    except BrokenPipeError:offset=len(data)
                    if offset==len(data):selector.unregister(stream);stream.close()
                else:
                    cap=(64*1024**2,1024**2)[index]
                    try:block=os.read(stream.fileno(),min(65536,cap-len(output[index])+1))
                    except BlockingIOError:continue
                    if not block:selector.unregister(stream);stream.close()
                    elif len(output[index])+len(block)>cap:raise ValueError('candidate output budget exceeded')
                    else:output[index].extend(block)
        p.wait(timeout=max(.001,deadline-time.monotonic()))
        if p.returncode:raise ValueError('nonzero candidate exit')
        return strict_json(bytes(output[0]))
    finally:
        old={sig:signal.signal(sig,signal.SIG_IGN) for sig in [signal.SIGINT,signal.SIGTERM]}
        try:
            if p.poll() is None:p.kill()
            p.wait();selector.close()
            for stream in streams:stream.close()
        finally:
            for sig,handler in old.items():signal.signal(sig,handler)


def main():
    if os.geteuid()==0:raise RuntimeError('public checker requires a nonroot development parent')
    def interrupted(signum,frame):
        signal.signal(signal.SIGTERM,signal.SIG_IGN)
        signal.signal(signal.SIGINT,signal.SIG_IGN)
        raise KeyboardInterrupt()
    signal.signal(signal.SIGTERM,interrupted)
    signal.signal(signal.SIGINT,interrupted)
    if len(sys.argv)!=2:raise ValueError('usage: python3 public_check.py submission')
    examples=strict_json(Path(__file__).with_name('examples.json').read_bytes())
    scratch=Path(os.environ.get('TMPDIR',str(Path(__file__).resolve().parent/'tmp')));scratch.mkdir(exist_ok=True)
    with tempfile.TemporaryDirectory(prefix='public-',dir=scratch) as root:
        root=Path(root);frozen=root/'submission';freeze(Path(sys.argv[1]),frozen)
        for i,example in enumerate(examples):
            with tempfile.TemporaryDirectory(prefix='case-',dir=root) as cwd:
                answer=capture(frozen/'main.py',json.dumps(example['input']).encode(),Path(cwd))
            if not matches(answer,example['expected']):raise ValueError(f'public example {i} differs')
    print(f'PASS: {len(examples)} public example')

if __name__=='__main__':
    try:main()
    except (Exception,KeyboardInterrupt) as error:
        print('FAIL: '+str(error or 'interrupted'),file=sys.stderr);sys.exit(1)

# Adapted CPU task subset; unused ingestion/SMT paths are omitted.
from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import numpy as np
import pandas as pd

from netnomos.ast import (
    BinaryTerm,
    BoolAnd,
    BoolConst,
    BoolNot,
    BoolOr,
    Compare,
    Constant,
    Exists,
    Formula,
    ForAll,
    FuncCall,
    Implies,
    IndexedRef,
    SymbolRef,
    Term,
    formula_to_string,
)
from netnomos.dataset import PreparedDataset
from netnomos.specs import FieldSpec, ValueType


def evaluate_formula_df(formula: Formula, prepared: PreparedDataset) -> pd.Series:
    try:
        return _evaluate_formula_vectorized(formula, prepared)
    except Exception:
        return prepared.dataframe.apply(
            lambda row: bool(evaluate_formula_row(formula, row.to_dict(), prepared.context_families)),
            axis=1,
        )


def evaluate_formula_row(formula: Formula, row: dict[str, Any], context_families: dict[str, list[str]], env: dict[str, Any] | None = None) -> bool:
    env = env or {}
    if isinstance(formula, BoolConst):
        return formula.value
    if isinstance(formula, Compare):
        left = evaluate_term_row(formula.left, row, context_families, env)
        right = evaluate_term_row(formula.right, row, context_families, env)
        return compare_values(formula.op, left, right)
    if isinstance(formula, BoolNot):
        return not evaluate_formula_row(formula.value, row, context_families, env)
    if isinstance(formula, BoolAnd):
        return all(evaluate_formula_row(v, row, context_families, env) for v in formula.values)
    if isinstance(formula, BoolOr):
        return any(evaluate_formula_row(v, row, context_families, env) for v in formula.values)
    if isinstance(formula, Implies):
        return (not evaluate_formula_row(formula.left, row, context_families, env)) or evaluate_formula_row(formula.right, row, context_families, env)
    if isinstance(formula, ForAll):
        return all(evaluate_formula_row(formula.body, row, context_families, {**env, formula.variable: value}) for value in formula.domain)
    if isinstance(formula, Exists):
        return any(evaluate_formula_row(formula.body, row, context_families, {**env, formula.variable: value}) for value in formula.domain)
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")


def evaluate_term_row(term: Term, row: dict[str, Any], context_families: dict[str, list[str]], env: dict[str, Any]) -> Any:
    if isinstance(term, Constant):
        return term.value
    if isinstance(term, SymbolRef):
        return row[term.name]
    if isinstance(term, IndexedRef):
        return row[resolve_indexed_name(term, env, context_families)]
    if isinstance(term, BinaryTerm):
        left = evaluate_term_row(term.left, row, context_families, env)
        right = evaluate_term_row(term.right, row, context_families, env)
        if term.op == "+":
            return left + right
        if term.op == "-":
            return left - right
        if term.op == "*":
            return left * right
        if term.op == "/":
            return left / right
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        args = [evaluate_term_row(arg, row, context_families, env) for arg in term.args]
        name = term.name.lower()
        if name == "min":
            return min(args)
        if name == "max":
            return max(args)
        if name == "sum":
            return sum(args)
        if name == "avg":
            return sum(args) / len(args)
        if name == "mod":
            if len(args) != 2:
                raise ValueError("MOD requires exactly two arguments")
            return args[0] % args[1]
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def compare_values(op: str, left: Any, right: Any) -> bool:
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    raise ValueError(f"Unsupported comparator: {op}")


def resolve_indexed_name(term: IndexedRef, env: dict[str, Any], context_families: dict[str, list[str]]) -> str:
    index = env.get(term.index, term.index)
    if isinstance(index, str) and index.isdigit():
        index = int(index)
    if not isinstance(index, int):
        raise ValueError(f"Indexed reference {formula_to_string(Compare('=', term, Constant(0)))} requires an integer index")
    if term.base not in context_families:
        raise KeyError(f"Unknown context family: {term.base}")
    return context_families[term.base][index]


def _evaluate_formula_vectorized(formula: Formula, prepared: PreparedDataset) -> pd.Series:
    if isinstance(formula, BoolConst):
        return pd.Series([formula.value] * len(prepared.dataframe), index=prepared.dataframe.index)
    if isinstance(formula, Compare):
        left = _evaluate_term_vectorized(formula.left, prepared)
        right = _evaluate_term_vectorized(formula.right, prepared)
        if formula.op == "=":
            return left == right
        if formula.op == "!=":
            return left != right
        if formula.op == ">":
            return left > right
        if formula.op == ">=":
            return left >= right
        if formula.op == "<":
            return left < right
        if formula.op == "<=":
            return left <= right
    if isinstance(formula, BoolNot):
        return ~_evaluate_formula_vectorized(formula.value, prepared)
    if isinstance(formula, BoolAnd):
        result = _evaluate_formula_vectorized(formula.values[0], prepared)
        for child in formula.values[1:]:
            result = result & _evaluate_formula_vectorized(child, prepared)
        return result
    if isinstance(formula, BoolOr):
        result = _evaluate_formula_vectorized(formula.values[0], prepared)
        for child in formula.values[1:]:
            result = result | _evaluate_formula_vectorized(child, prepared)
        return result
    if isinstance(formula, Implies):
        left = _evaluate_formula_vectorized(formula.left, prepared)
        right = _evaluate_formula_vectorized(formula.right, prepared)
        return (~left) | right
    raise ValueError("Quantified formulas require row-wise evaluation")


def _evaluate_term_vectorized(term: Term, prepared: PreparedDataset) -> pd.Series | Any:
    frame = prepared.dataframe
    if isinstance(term, Constant):
        return term.value
    if isinstance(term, SymbolRef):
        return frame[term.name]
    if isinstance(term, IndexedRef):
        name = resolve_indexed_name(term, {}, prepared.context_families)
        return frame[name]
    if isinstance(term, BinaryTerm):
        left = _evaluate_term_vectorized(term.left, prepared)
        right = _evaluate_term_vectorized(term.right, prepared)
        if term.op == "+":
            return left + right
        if term.op == "-":
            return left - right
        if term.op == "*":
            return left * right
        if term.op == "/":
            return left / right
    if isinstance(term, FuncCall):
        columns = [_evaluate_term_vectorized(arg, prepared) for arg in term.args]
        name = term.name.lower()
        if all(isinstance(col, pd.Series) for col in columns):
            tmp = pd.concat(columns, axis=1)
            if name == "min":
                return tmp.min(axis=1)
            if name == "max":
                return tmp.max(axis=1)
            if name == "sum":
                return tmp.sum(axis=1)
            if name == "avg":
                return tmp.mean(axis=1)
            if name == "mod":
                if len(columns) != 2:
                    raise ValueError("MOD requires exactly two arguments")
                return columns[0] % columns[1]
        values = [col if not isinstance(col, pd.Series) else col.iloc[0] for col in columns]
        if name == "min":
            return min(values)
        if name == "max":
            return max(values)
        if name == "sum":
            return sum(values)
        if name == "avg":
            return sum(values) / len(values)
        if name == "mod":
            if len(values) != 2:
                raise ValueError("MOD requires exactly two arguments")
            return values[0] % values[1]
    raise TypeError(f"Unsupported vectorized term: {type(term)!r}")
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True, slots=True)
class Constant:
    value: Any


@dataclass(frozen=True, slots=True)
class SymbolRef:
    name: str


@dataclass(frozen=True, slots=True)
class IndexedRef:
    base: str
    index: int | str


@dataclass(frozen=True, slots=True)
class BinaryTerm:
    op: str
    left: Term
    right: Term


@dataclass(frozen=True, slots=True)
class FuncCall:
    name: str
    args: tuple[Term, ...]


Term = Constant | SymbolRef | IndexedRef | BinaryTerm | FuncCall


@dataclass(frozen=True, slots=True)
class Compare:
    op: str
    left: Term
    right: Term


@dataclass(frozen=True, slots=True)
class BoolConst:
    value: bool


@dataclass(frozen=True, slots=True)
class BoolNot:
    value: Formula


@dataclass(frozen=True, slots=True)
class BoolAnd:
    values: tuple[Formula, ...]


@dataclass(frozen=True, slots=True)
class BoolOr:
    values: tuple[Formula, ...]


@dataclass(frozen=True, slots=True)
class Implies:
    left: Formula
    right: Formula


@dataclass(frozen=True, slots=True)
class ForAll:
    variable: str
    domain: tuple[Any, ...]
    body: Formula


@dataclass(frozen=True, slots=True)
class Exists:
    variable: str
    domain: tuple[Any, ...]
    body: Formula


Formula = Compare | BoolConst | BoolNot | BoolAnd | BoolOr | Implies | ForAll | Exists


def constant(value: Any) -> Constant:
    return Constant(value=value)


def render_keyword(value: str) -> str:
    return value.upper()


def formula_to_dict(node: Formula) -> dict[str, Any]:
    if isinstance(node, Compare):
        return {
            "kind": "compare",
            "op": node.op,
            "left": term_to_dict(node.left),
            "right": term_to_dict(node.right),
        }
    if isinstance(node, BoolConst):
        return {"kind": "bool", "value": node.value}
    if isinstance(node, BoolNot):
        return {"kind": "not", "value": formula_to_dict(node.value)}
    if isinstance(node, BoolAnd):
        return {"kind": "and", "values": [formula_to_dict(v) for v in node.values]}
    if isinstance(node, BoolOr):
        return {"kind": "or", "values": [formula_to_dict(v) for v in node.values]}
    if isinstance(node, Implies):
        return {
            "kind": "implies",
            "left": formula_to_dict(node.left),
            "right": formula_to_dict(node.right),
        }
    if isinstance(node, ForAll):
        return {
            "kind": "forall",
            "variable": node.variable,
            "domain": list(node.domain),
            "body": formula_to_dict(node.body),
        }
    if isinstance(node, Exists):
        return {
            "kind": "exists",
            "variable": node.variable,
            "domain": list(node.domain),
            "body": formula_to_dict(node.body),
        }
    raise TypeError(f"Unsupported formula node: {type(node)!r}")


def term_to_dict(node: Term) -> dict[str, Any]:
    if isinstance(node, Constant):
        return {"kind": "constant", "value": node.value}
    if isinstance(node, SymbolRef):
        return {"kind": "symbol", "name": node.name}
    if isinstance(node, IndexedRef):
        return {"kind": "indexed", "base": node.base, "index": node.index}
    if isinstance(node, BinaryTerm):
        return {
            "kind": "binary",
            "op": node.op,
            "left": term_to_dict(node.left),
            "right": term_to_dict(node.right),
        }
    if isinstance(node, FuncCall):
        return {"kind": "call", "name": node.name, "args": [term_to_dict(v) for v in node.args]}
    raise TypeError(f"Unsupported term node: {type(node)!r}")


def formula_from_dict(data: dict[str, Any]) -> Formula:
    kind = data["kind"]
    if kind == "compare":
        return Compare(data["op"], term_from_dict(data["left"]), term_from_dict(data["right"]))
    if kind == "bool":
        return BoolConst(bool(data["value"]))
    if kind == "not":
        return BoolNot(formula_from_dict(data["value"]))
    if kind == "and":
        return BoolAnd(tuple(formula_from_dict(v) for v in data["values"]))
    if kind == "or":
        return BoolOr(tuple(formula_from_dict(v) for v in data["values"]))
    if kind == "implies":
        return Implies(formula_from_dict(data["left"]), formula_from_dict(data["right"]))
    if kind == "forall":
        return ForAll(variable=data["variable"], domain=tuple(data["domain"]), body=formula_from_dict(data["body"]))
    if kind == "exists":
        return Exists(variable=data["variable"], domain=tuple(data["domain"]), body=formula_from_dict(data["body"]))
    raise ValueError(f"Unsupported formula kind: {kind}")


def term_from_dict(data: dict[str, Any]) -> Term:
    kind = data["kind"]
    if kind == "constant":
        return Constant(data["value"])
    if kind == "symbol":
        return SymbolRef(data["name"])
    if kind == "indexed":
        return IndexedRef(data["base"], data["index"])
    if kind == "binary":
        return BinaryTerm(data["op"], term_from_dict(data["left"]), term_from_dict(data["right"]))
    if kind == "call":
        return FuncCall(data["name"], tuple(term_from_dict(v) for v in data["args"]))
    raise ValueError(f"Unsupported term kind: {kind}")


def term_to_string(node: Term) -> str:
    if isinstance(node, Constant):
        return repr(node.value) if isinstance(node.value, str) else str(node.value)
    if isinstance(node, SymbolRef):
        return node.name
    if isinstance(node, IndexedRef):
        return f"{node.base}[{node.index}]"
    if isinstance(node, BinaryTerm):
        return f"({term_to_string(node.left)} {node.op} {term_to_string(node.right)})"
    if isinstance(node, FuncCall):
        return f"{render_keyword(node.name)}({', '.join(term_to_string(v) for v in node.args)})"
    raise TypeError(f"Unsupported term node: {type(node)!r}")


def formula_to_string(node: Formula) -> str:
    if isinstance(node, Compare):
        return f"{term_to_string(node.left)} {node.op} {term_to_string(node.right)}"
    if isinstance(node, BoolConst):
        return render_keyword("true") if node.value else render_keyword("false")
    if isinstance(node, BoolNot):
        return f"{render_keyword('not')} ({formula_to_string(node.value)})"
    if isinstance(node, BoolAnd):
        return f" {render_keyword('and')} ".join(f"({formula_to_string(v)})" for v in node.values)
    if isinstance(node, BoolOr):
        return f" {render_keyword('or')} ".join(f"({formula_to_string(v)})" for v in node.values)
    if isinstance(node, Implies):
        return f"({formula_to_string(node.left)}) -> ({formula_to_string(node.right)})"
    if isinstance(node, ForAll):
        return (
            f"{render_keyword('forall')} {node.variable} {render_keyword('in')} "
            f"{{{', '.join(map(str, node.domain))}}}: {formula_to_string(node.body)}"
        )
    if isinstance(node, Exists):
        return (
            f"{render_keyword('exists')} {node.variable} {render_keyword('in')} "
            f"{{{', '.join(map(str, node.domain))}}}: {formula_to_string(node.body)}"
        )
    raise TypeError(f"Unsupported formula node: {type(node)!r}")

