"""Random protocol-valid job generator for differential testing."""
import random

NUMERIC = ('time', 'size', 'count')
ALLTYPES = ('time', 'size', 'count', 'id', 'flag')
OPS_NUMERIC = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
OPS_EQNE = ('eq', 'ne')


def make_term(rng, fields_by_type, numeric_type, K, allow_sum=True):
    kind = rng.choice(['ref', 'const', 'sum', 'scale'] if allow_sum else ['ref', 'const'])
    if numeric_type not in NUMERIC:
        kind = rng.choice(['ref', 'const'])
    if kind == 'const':
        if numeric_type in NUMERIC:
            v = rng.choice([0, 1, 2, 3, 5, 10, 11, 12, 100, 1000, 1000000, rng.randint(0, 20)])
        else:
            v = rng.choice([0, 1, 2, 3, 5, 10, 11, 17, rng.randint(0, 20)])
        return {'const': v, 'type': numeric_type}
    if kind == 'sum' and numeric_type in NUMERIC:
        refs = []
        pool = []
        for slot in range(K):
            for f in fields_by_type[numeric_type]:
                pool.append([slot, f])
        cnt = rng.randint(1, min(K, max(1, len(pool))))
        for r in rng.sample(pool, cnt):
            refs.append(r)
        if not refs:
            return {'ref': [0, fields_by_type[numeric_type][0]]}
        return {'sum': refs}
    if kind == 'scale' and numeric_type in NUMERIC:
        f = rng.choice(fields_by_type[numeric_type])
        return {'scale': rng.choice([0, 1, 2, 3, 10, 65535]), 'ref': [rng.randrange(K), f]}
    f = rng.choice(fields_by_type[numeric_type])
    return {'ref': [rng.randrange(K), f]}


def make_predicate(rng, fields, fields_by_type, K):
    kind = rng.choice(['cmp', 'cmp', 'cmp', 'any', 'all'])
    if kind == 'cmp':
        t = rng.choice(list(fields_by_type.keys()))
        while not fields_by_type[t]:
            t = rng.choice(list(fields_by_type.keys()))
        left = make_term(rng, fields_by_type, t, K)
        right = make_term(rng, fields_by_type, t, K)
        op = rng.choice(OPS_NUMERIC if t in NUMERIC else OPS_EQNE)
        return {'kind': 'cmp', 'left': left, 'op': op, 'right': right}
    name = rng.choice(list(fields_by_type.keys()))
    while not fields_by_type[name]:
        name = rng.choice(list(fields_by_type.keys()))
    fname = rng.choice(fields_by_type[name])
    op = rng.choice(OPS_NUMERIC if name in NUMERIC else OPS_EQNE)
    value = rng.choice([0, 1, 2, 3, 5, 10, 11, 12, 100, 1000000, rng.randint(0, 20)])
    return {'kind': kind, 'field': fname, 'op': op, 'value': value}


def make_job(rng, max_universe=600, max_pred=8, max_train=12, max_width=4, max_queries=8):
    nf = rng.randint(1, 4)
    K = rng.randint(1, 4)
    while K * nf > 16:
        nf = rng.randint(1, 4)
        K = rng.randint(1, 4)
    fields = []
    names = ['alpha', 'beta', 'gamma', 'delta', 'eps', 'zeta', 'eta', 'theta'][:nf]
    rng.shuffle(names)
    for i in range(nf):
        t = rng.choice(ALLTYPES)
        size = rng.randint(1, 4)
        if rng.random() < 0.15:
            size = 1
        domain = sorted(rng.sample(range(0, 25), size))
        if rng.random() < 0.1:
            domain = [0]
        fields.append({'name': names[i], 'type': t, 'domain': domain})
    fields_by_type = {t: [f['name'] for f in fields if f['type'] == t] for t in ALLTYPES}
    # keep universe small
    total = 1
    for f in fields:
        total *= len(f['domain']) ** K
    while total > max_universe:
        for f in fields:
            if len(f['domain']) > 1 and total > max_universe:
                f['domain'] = f['domain'][:len(f['domain']) - 1]
                total //= K
                break
        else:
            break
    P = rng.randint(0, max_pred)
    predicates = [make_predicate(rng, fields, fields_by_type, K) for _ in range(P)]
    width = rng.randint(1, max_width)
    train = []
    doms = [f['domain'] for f in fields]
    for _ in range(rng.randint(1, max_train)):
        w = [[rng.choice(d) for d in doms] for _ in range(K)]
        train.append(w)
    if rng.random() < 0.3 and train:
        train.append(train[0]
                     if isinstance(train[0], list) and all(isinstance(r, list) for r in train[0])
                     else train[0])
    # approvals: random clauses, some possibly discovered
    approved = []
    seen = set()
    for _ in range(rng.randint(0, 8)):
        if P == 0:
            break
        size = rng.randint(1, min(width, P))
        clause = tuple(sorted(rng.sample(range(P), size)))
        if clause in seen:
            continue
        seen.add(clause)
        approved.append(list(clause))
    queries = []
    for _ in range(max_queries):
        fixed = []
        used = set()
        cells = [(s, f['name']) for s in range(K) for f in fields]
        for _ in range(rng.randint(0, min(3, len(cells)))):
            c = rng.choice(cells)
            if c in used:
                continue
            used.add(c)
            fixed.append({'ref': [c[0], c[1]], 'value': rng.choice([f for f in fields if f['name'] == c[1]][0]['domain'])})
        rest = [c for c in cells if c not in used]
        target = list(rng.choice(rest))
        prefix = rng.choice(['', '0', '00', '1', '01', '10', '2', '5', '11', '12', '123', '9999999',
                             '1234567', '0' * 7, ''.join(rng.choice('0123456789') for _ in range(rng.randint(0, 7)))])
        queries.append({'target': target, 'prefix': prefix, 'fixed': fixed})
    return {'fields': fields, 'slots': K, 'predicates': predicates, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}
