"""Second independent reference: numpy arrays, itertools clauses, string scans."""
import itertools
import numpy as np

OPS = {'eq': np.equal, 'ne': np.not_equal, 'lt': np.less,
       'le': np.less_equal, 'gt': np.greater, 'ge': np.greater_equal}


def compile_job(job):
    fields = job['fields']
    nf = len(fields)
    K = job['slots']
    fpos = {f['name']: i for i, f in enumerate(fields)}
    doms = [list(f['domain']) for f in fields]
    ncells = K * nf
    radices = [len(doms[c % nf]) for c in range(ncells)]

    def cellidx(ref):
        return ref[0] * nf + fpos[ref[1]]

    U = int(np.prod(radices)) if radices else 1
    uni = np.zeros((U, ncells), dtype=np.int64)
    for c in range(ncells):
        stride = int(np.prod(radices[c + 1:])) if c + 1 < len(radices) else 1
        col = np.array(doms[c % nf], dtype=np.int64)[(np.arange(U) // stride) % radices[c]]
        uni[:, c] = col
    train = np.array([[v for row in w for v in row] for w in job['train']], dtype=np.int64)

    def tval(term, table):
        if 'const' in term:
            return np.full(table.shape[0], int(term['const']), dtype=np.int64)
        if 'sum' in term:
            out = np.zeros(table.shape[0], dtype=np.int64)
            for r in term['sum']:
                out = out + table[:, cellidx(r)]
            return out
        col = table[:, cellidx(term['ref'])]
        if 'scale' in term:
            return col * int(term['scale'])
        return col

    def pval(p, table):
        if p['kind'] == 'cmp':
            return OPS[p['op']](tval(p['left'], table), tval(p['right'], table))
        idx = fpos[p['field']]
        cols = [table[:, s * nf + idx] for s in range(K)]
        res = OPS[p['op']](cols[0], int(p['value']))
        for col in cols[1:]:
            res = np.logical_or(res, OPS[p['op']](col, int(p['value']))) if p['kind'] == 'any' \
                else np.logical_and(res, OPS[p['op']](col, int(p['value'])))
        return res

    P = len(job['predicates'])
    Tt = [pval(p, train) for p in job['predicates']]
    Tu = [pval(p, uni) for p in job['predicates']]
    n = train.shape[0]

    rules = []
    for size in range(1, job['width'] + 1):
        for clause in itertools.combinations(range(P), size):
            ors = Tt[clause[0]]
            for l in clause[1:]:
                ors = ors | Tt[l]
            if not ors.all():
                continue
            wit = []
            ok = True
            for l in clause:
                others = [x for x in clause if x != l]
                if others:
                    ov = Tt[others[0]]
                    for x in others[1:]:
                        ov = ov | Tt[x]
                else:
                    ov = np.zeros(n, dtype=bool)
                m = Tt[l] & ~ov
                idx = int(np.argmax(m)) if m.any() else None
                if idx is None:
                    ok = False
                    break
                wit.append(idx)
            if not ok:
                continue
            uo = Tu[clause[0]]
            for l in clause[1:]:
                uo = uo | Tu[l]
            if uo.all():
                continue
            ce = int(np.argmax(~uo))
            rules.append({'clause': list(clause), 'witnesses': wit, 'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))
    approved = {tuple(a) for a in job['approved']}
    active = [list(r['clause']) for r in rules if tuple(r['clause']) in approved]

    answers = []
    theory = np.ones(U, dtype=bool)
    for c in active:
        v = Tu[c[0]]
        for l in c[1:]:
            v = v | Tu[l]
        theory = theory & v
    for q in job['queries']:
        sel = theory.copy()
        for b in q['fixed']:
            sel = sel & (uni[:, cellidx(b['ref'])] == int(b['value']))
        tcell = cellidx(q['target'])
        prefix = q['prefix']
        spell = np.array([str(v) for v in uni[:, tcell]], dtype=object)
        keep = np.array([s.startswith(prefix) for s in spell], dtype=bool)
        comp = np.flatnonzero(sel & keep)
        tokens = [d for d in '0123456789'
                  if any(s.startswith(prefix + d) for s in spell[comp])]
        if any(s == prefix for s in spell[comp]):
            tokens.append('END')
        answers.append({'count': int(comp.size), 'tokens': tokens,
                        'witness': int(comp[0]) if comp.size else None})
    return {'rules': rules, 'active': active, 'answers': answers}
