    for slot in range(K):
        for i in range(nf):
            for v in (0, 1):
                preds.append({'kind': 'cmp', 'left': {'ref': [slot, f'b{i}']}, 'op': 'eq',
                              'right': {'const': v, 'type': 'count'}})
    extra = [
        {'kind': 'any', 'field': 'b0', 'op': 'ge', 'value': 1},
        {'kind': 'all', 'field': 'b1', 'op': 'le', 'value': 0},
        {'kind': 'cmp', 'left': {'sum': [[0, 'b0'], [1, 'b1']]}, 'op': 'ge',
         'right': {'const': 1, 'type': 'count'}},
        {'kind': 'cmp', 'left': {'sum': [[2, 'b2'], [3, 'b3'], [0, 'b0']]}, 'op': 'le',
         'right': {'const': 1, 'type': 'count'}},
        {'kind': 'cmp', 'left': {'scale': 3, 'ref': [1, 'b2']}, 'op': 'ge',
         'right': {'ref': [0, 'b3']}},
    ]
    preds = preds + extra
    rng.shuffle(preds)
    preds = preds[:32]
    # train windows with restricted zero counts to create many minimal conflicts
    train = []
    style = rng.randrange(3)
    for _ in range(rng.randint(1, 40)):
        if style == 0:
            w = [rng.choice([0, 1]) for _ in range(K * nf)]
        elif style == 1:
            w = [1] * (K * nf)
            for c in rng.sample(range(K * nf), rng.randint(0, 3)):
                w[c] = 0
        else:
            w = [0] * (K * nf)
            for c in rng.sample(range(K * nf), rng.randint(0, 3)):
                w[c] = 1
        train.append([w[i * nf:(i + 1) * nf] for i in range(K)])
    queries = []
    for _ in range(rng.randint(0, 6)):
        fixed = [{'ref': [rng.randrange(K), f'b{rng.randrange(nf)}'], 'value': rng.choice([0, 1])}
                 for _ in range(rng.randint(0, 2))]
        used = {tuple(f['ref']) for f in fixed}
        rest = [[s, f'b{i}'] for s in range(K) for i in range(nf) if [s, f'b{i}'] not in used]
        if not rest:
            continue
        queries.append({'target': list(rng.choice(rest)), 'prefix': rng.choice(['', '0', '1', '01', '10']),
                        'fixed': fixed})
    width = rng.choice([1, 2, 3, 4])
    approved = []
    seen = set()
    for _ in range(rng.randint(0, 6)):
        cl = tuple(sorted(rng.sample(range(len(preds)), rng.randint(1, min(width, len(preds))))))
        if cl not in seen:
            seen.add(cl)
            approved.append(list(cl))
    return {'fields': fields, 'slots': K, 'predicates': preds, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}


